package app.goosle

/** Spotting AI-generated and mass-produced "slop" from the words around it. */
object Slop {
    /** Phrases that usually mean AI-generated or low-effort mass-produced content. Editable in the app. */
    val DEFAULT_WORDS = listOf(
        "ai generated", "ai-generated", "made with ai", "made by ai", "100% ai", "generated by ai",
        "#ai", "#aiart", "#aivideo", "#aigenerated", "#aimusic", "#aianimation", "#aiartwork", "#midjourney",
        "ai art", "ai music", "ai song", "ai cover", "ai voice", "ai animation", "ai story", "ai video",
        "ai movie", "ai trailer", "ai influencer", "ai girl", "ai baby", "ai animals", "ai short film",
        "midjourney", "stable diffusion", "sora", "veo 3", "veo3", "suno", "udio", "kling ai", "runway gen",
        "chatgpt wrote", "written by chatgpt", "reddit stories", "#redditstories", "text to speech",
        "faceless channel", "aita",
    )

    private val cache = HashMap<String, Regex>()

    /** Whole-word/phrase matching, so "sora" doesn't hit "Soraya" and "#ai" doesn't hit "#aircraft". */
    fun match(text: String, words: List<String>): String? {
        if (text.isBlank()) return null
        val t = text.lowercase()
        for (w in words) {
            val word = w.trim().lowercase()
            if (word.isEmpty()) continue
            val re = synchronized(cache) {
                cache.getOrPut(word) { Regex("(?<![\\p{L}\\p{N}])${Regex.escape(word)}(?![\\p{L}\\p{N}])") }
            }
            if (re.containsMatchIn(t)) return word
        }
        return null
    }
}
